import { InstancedMesh, Object3D, DodecahedronGeometry, Matrix4 } from 'three';

/**
 * Seeded PRNG (mulberry32). Fast, decent quality, fully deterministic.
 */
export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Bridson's Poisson-disk sampling (2007), O(n) using a background grid.
 *
 * @param {object} opts
 * @param {number} opts.width   extent along x
 * @param {number} opts.depth   extent along z
 * @param {number} opts.minDist minimum distance between any two points
 * @param {number} opts.seed    RNG seed
 * @param {number} [opts.k=30]  attempts per active point before rejection
 * @returns {Array<{x:number,z:number}>}
 */
export function poissonDisk({ width, depth, minDist, seed, k = 30 }) {
  const rng = mulberry32(seed);

  // Grid cell size so each cell holds at most one sample.
  const cellSize = minDist / Math.SQRT2;
  const gw = Math.ceil(width / cellSize);
  const gh = Math.ceil(depth / cellSize);
  const grid = new Int32Array(gw * gh).fill(-1); // index of point or -1

  const points = [];
  const toCell = (p) => [
    Math.min(gw - 1, Math.floor(p.x / cellSize)),
    Math.min(gh - 1, Math.floor(p.z / cellSize)),
  ];
  const gridIndex = (cx, cz) => cz * gw + cx;
  const insert = (i) => {
    const [cx, cz] = toCell(points[i]);
    grid[gridIndex(cx, cz)] = i;
  };

  // Distance check against neighbors within radius 2 cells.
  const tooClose = (p) => {
    const [cx, cz] = toCell(p);
    for (let dz = -2; dz <= 2; dz++) {
      const nz = cz + dz;
      if (nz < 0 || nz >= gh) continue;
      for (let dx = -2; dx <= 2; dx++) {
        const nx = cx + dx;
        if (nx < 0 || nx >= gw) continue;
        const idx = grid[gridIndex(nx, nz)];
        if (idx === -1) continue;
        const q = points[idx];
        const ddx = q.x - p.x;
        const ddz = q.z - p.z;
        if (ddx * ddx + ddz * ddz < minDist * minDist) return true;
      }
    }
    return false;
  };

  // Initial point.
  const first = { x: rng() * width, z: rng() * depth };
  points.push(first);
  insert(0);
  const active = [0];

  while (active.length > 0) {
    // Pick a random active point.
    const ai = Math.floor(rng() * active.length);
    const p = points[active[ai]];

    // Try up to k candidate points in the annulus [minDist, 2*minDist).
    let placed = false;
    for (let attempt = 0; attempt < k; attempt++) {
      const angle = rng() * Math.PI * 2;
      const r = minDist * (1 + rng()); // uniform-ish in [minDist, 2*minDist)
      const c = {
        x: p.x + Math.cos(angle) * r,
        z: p.z + Math.sin(angle) * r,
      };
      if (c.x < 0 || c.x >= width || c.z < 0 || c.z >= depth) continue;
      if (tooClose(c)) continue;
      points.push(c);
      insert(points.length - 1);
      active.push(points.length - 1);
      placed = true;
      break;
    }

    if (!placed) {
      // Swap-remove the exhausted point.
      active[ai] = active[active.length - 1];
      active.pop();
    }
  }

  return points;
}

/**
 * Build an InstancedMesh of dodecahedron rocks, one per point, with a seeded
 * scale in [0.3, 1.0] and random rotation about Y.
 *
 * @param {Array<{x:number,z:number}>} points
 * @param {number} seed
 * @returns {InstancedMesh}
 */
export function scatterRocks(points, seed) {
  const rng = mulberry32(seed);
  const geometry = new DodecahedronGeometry(0.5);
  const material = new MeshLambertMaterialSafe();
  const mesh = new InstancedMesh(geometry, material, points.length);

  const m = new Matrix4();
  const obj = new Object3D();
  for (let i = 0; i < points.length; i++) {
    const scale = 0.3 + rng() * 0.7; // [0.3, 1.0]
    obj.position.set(points[i].x, 0, points[i].z);
    obj.rotation.set(0, rng() * Math.PI * 2, 0);
    obj.scale.setScalar(scale);
    obj.updateMatrix();
    mesh.setMatrixAt(i, obj.matrix);
  }
  mesh.instanceMatrix.needsUpdate = true;
  void m;

  return mesh;
}

// Local import shim so the file only pulls what it needs from three.
import { MeshLambertMaterial as MeshLambertMaterialSafe } from 'three';

