import { describe, it, expect } from 'vitest';
import { poissonDisk, scatterRocks } from '../src/scatter.js';

const W = 30;
const D = 30;
const MIN_DIST = 2;

describe('poissonDisk', () => {
  const points = poissonDisk({ width: W, depth: D, minDist: MIN_DIST, seed: 42 });

  it('keeps every pair of points at least minDist apart (exhaustive)', () => {
    const md2 = MIN_DIST * MIN_DIST;
    for (let i = 0; i < points.length; i++) {
      for (let j = i + 1; j < points.length; j++) {
        const dx = points[i].x - points[j].x;
        const dz = points[i].z - points[j].z;
        const d2 = dx * dx + dz * dz;
        expect(
          d2,
          `points ${i} (${points[i].x},${points[i].z}) and ${j} (${points[j].x},${points[j].z}) too close: dist^2=${d2}`
        ).toBeGreaterThanOrEqual(md2);
      }
    }
  });

  it('places all points inside the rectangle', () => {
    for (const p of points) {
      expect(p.x).toBeGreaterThanOrEqual(0);
      expect(p.x).toBeLessThan(W);
      expect(p.z).toBeGreaterThanOrEqual(0);
      expect(p.z).toBeLessThan(D);
    }
  });

  it('reaches at least 0.5 * area / minDist^2 samples', () => {
    const expected = 0.5 * (W * D) / (MIN_DIST * MIN_DIST);
    expect(points.length).toBeGreaterThanOrEqual(expected);
  });

  it('is deterministic for the same seed', () => {
    const a = poissonDisk({ width: W, depth: D, minDist: MIN_DIST, seed: 1337 });
    const b = poissonDisk({ width: W, depth: D, minDist: MIN_DIST, seed: 1337 });
    expect(a.length).toBe(b.length);
    for (let i = 0; i < a.length; i++) {
      expect(a[i].x).toBe(b[i].x);
      expect(a[i].z).toBe(b[i].z);
    }

    const c = poissonDisk({ width: W, depth: D, minDist: MIN_DIST, seed: 99 });
    const differs =
      c.length !== a.length ||
      a.some((p, i) => p.x !== c[i].x || p.z !== c[i].z);
    expect(differs).toBe(true);
  });

  it('returns plain {x, z} objects', () => {
    for (const p of points) {
      expect(Object.keys(p).sort()).toEqual(['x', 'z']);
      expect(typeof p.x).toBe('number');
      expect(typeof p.z).toBe('number');
    }
  });
});

describe('scatterRocks', () => {
  it('creates an InstancedMesh with instance count equal to point count', () => {
    const pts = poissonDisk({ width: W, depth: D, minDist: MIN_DIST, seed: 7 });
    const mesh = scatterRocks(pts, 1234);
    expect(mesh.count).toBe(pts.length);
    expect(mesh.isInstancedMesh).toBe(true);
  });

  it('produces deterministic per-instance transforms for the same seed', () => {
    const pts = poissonDisk({ width: W, depth: D, minDist: MIN_DIST, seed: 5 });
    const a = scatterRocks(pts, 77);
    const b = scatterRocks(pts, 77);
    for (let i = 0; i < pts.length; i++) {
      expect(Array.from(a.instanceMatrix.array)).toEqual(
        Array.from(b.instanceMatrix.array)
      );
    }
  });
});

